import 'package:flutter_test/flutter_test.dart';
import 'package:auren/features/profile_privacy/domain/profile_privacy_resolver.dart';
void main(){const p=ProfilePrivacyResolver();const rules=[ProfileFieldRule(field:'bio',visibility:ProfileVisibility.public),ProfileFieldRule(field:'photos',visibility:ProfileVisibility.followers)];test('respects field audience',(){expect(p.canView(field:'bio',audience:ProfileAudience.public,rules:rules,blocked:false),isTrue);expect(p.canView(field:'photos',audience:ProfileAudience.public,rules:rules,blocked:false),isFalse);expect(p.canView(field:'photos',audience:ProfileAudience.followers,rules:rules,blocked:false),isTrue);});test('duplicate field rules fail closed',(){expect(p.canView(field:'bio',audience:ProfileAudience.public,rules:[...rules,const ProfileFieldRule(field:'bio',visibility:ProfileVisibility.private)],blocked:false),isFalse);});test('unknown fields and blocked accounts are denied',(){expect(p.canView(field:'unknown',audience:ProfileAudience.public,rules:rules,blocked:false),isFalse);expect(p.canView(field:'bio',audience:ProfileAudience.followers,rules:rules,blocked:true),isFalse);});}
